#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;

vector<vector<int>> generate_cycles(int n) {
    vector<vector<int>> cycles;
    for (int i = 1; i <= n; ++i) {
        cycles.push_back({i});
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = i + 1; j <= n; ++j) {
            cycles.push_back({j, i});
        }
    }
    sort(cycles.begin(), cycles.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[0] < b[0];
    });
    return cycles;
}

vector<int> construct_permutation(const vector<vector<int>>& cycles, int n) {
    vector<int> perm(n + 1);
    for (const auto& cycle : cycles) {
        int len = cycle.size();
        for (int i = 0; i < len; ++i) {
            perm[cycle[i]] = cycle[(i + 1) % len];
        }
    }
    return perm;
}

bool is_fixed(const vector<int>& perm, int n) {
    vector<vector<int>> cycles;
    vector<bool> visited(n + 1, false);
    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            vector<int> cycle;
            int current = i;
            while (!visited[current]) {
                visited[current] = true;
                cycle.push_back(current);
                current = perm[current];
            }
            cycles.push_back(cycle);
        }
    }
    for (auto& cycle : cycles) {
        int max_val = *max_element(cycle.begin(), cycle.end());
        auto it = find(cycle.begin(), cycle.end(), max_val);
        rotate(cycle.begin(), it, cycle.end());
    }
    sort(cycles.begin(), cycles.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[0] < b[0];
    });
    vector<int> reconstructed;
    for (const auto& cycle : cycles) {
        for (int num : cycle) {
            reconstructed.push_back(num);
        }
    }
    vector<int> original;
    for (int i = 1; i <= n; ++i) {
        original.push_back(perm[i]);
    }
    return original == reconstructed;
}

int main() {
    ll n, k;
    cin >> n >> k;
    vector<vector<int>> valid_perms;
    vector<vector<int>> cycles = generate_cycles(n);
    vector<vector<int>> all_cycles;
    for (int mask = 0; mask < (1 << cycles.size()); ++mask) {
        vector<vector<int>> selected;
        for (int i = 0; i < cycles.size(); ++i) {
            if (mask & (1 << i)) {
                selected.push_back(cycles[i]);
            }
        }
        vector<int> perm = construct_permutation(selected, n);
        if (is_fixed(perm, n)) {
            valid_perms.push_back(perm);
        }
    }
    sort(valid_perms.begin(), valid_perms.end());
    vector<int> result = valid_perms[k - 1];
    for (int i = 1; i <= n; ++i) {
        cout << result[i] << " ";
    }
    cout << endl;
    return 0;
}
