#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;

vector<int> build_perm(const vector<vector<int>>& cycles, int n) {
    vector<int> perm(n + 1);
    for (const auto& cyc : cycles) {
        for (int i = 0; i < cyc.size(); ++i) {
            int from = cyc[i];
            int to = cyc[(i + 1) % cyc.size()];
            perm[from] = to;
        }
    }
    return perm;
}

vector<vector<int>> generate_cycles(int n) {
    vector<vector<int>> result;
    vector<int> used(n + 1, 0);
    vector<int> current;

    function<void(int)> backtrack = [&](int start) {
        if (current.size() > 0) {
            result.push_back(current);
        }
        for (int i = start; i <= n; ++i) {
            if (!used[i]) {
                used[i] = 1;
                current.push_back(i);
                backtrack(i + 1);
                current.pop_back();
                used[i] = 0;
            }
        }
    };

    backtrack(1);
    return result;
}

vector<vector<int>> get_all_cycle_decompositions(int n) {
    vector<vector<int>> cycles = generate_cycles(n);
    vector<vector<vector<int>>> all_decomps;

    function<void(int, vector<vector<int>>)> solve = [&](int pos, vector<vector<int>> current_decomp) {
        if (pos > n) {
            all_decomps.push_back(current_decomp);
            return;
        }
        if (pos == 1) {
            for (const auto& cyc : cycles) {
                if (cyc[0] == 1) {
                    vector<int> new_used = cyc;
                    sort(new_used.begin(), new_used.end());
                    vector<int> used(n + 1, 0);
                    for (int x : new_used) used[x] = 1;
                    vector<vector<int>> new_decomp = current_decomp;
                    new_decomp.push_back(cyc);
                    solve(pos + 1, new_decomp);
                }
            }
        } else {
            vector<int> used(n + 1, 0);
            for (const auto& c : current_decomp) {
                for (int x : c) used[x] = 1;
            }
            for (const auto& cyc : cycles) {
                bool valid = true;
                for (int x : cyc) {
                    if (used[x]) {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    vector<vector<int>> new_decomp = current_decomp;
                    new_decomp.push_back(cyc);
                    solve(pos + 1, new_decomp);
                }
            }
        }
    };

    solve(1, {});
    return all_decomps[0]; // This approach is incorrect for large n
}

vector<vector<int>> get_valid_decompositions(int n) {
    vector<vector<int>> result;
    vector<int> perm(n + 1);
    vector<int> used(n + 1, 0);

    function<void(int)> backtrack = [&](int pos) {
        if (pos > n) {
            result.push_back(perm);
            return;
        }
        for (int i = 1; i <= n; ++i) {
            if (!used[i]) {
                used[i] = 1;
                perm[pos] = i;
                backtrack(pos + 1);
                used[i] = 0;
            }
        }
    };

    backtrack(1);
    return result;
}

bool is_valid_permutation(const vector<int>& perm, int n) {
    vector<int> visited(n + 1, 0);
    vector<vector<int>> cycles;

    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            vector<int> cycle;
            int current = i;
            while (!visited[current]) {
                visited[current] = 1;
                cycle.push_back(current);
                current = perm[current];
            }
            cycles.push_back(cycle);
        }
    }

    vector<vector<int>> standard_cycles;
    for (auto& cyc : cycles) {
        int max_val = *max_element(cyc.begin(), cyc.end());
        auto it = find(cyc.begin(), cyc.end(), max_val);
        rotate(cyc.begin(), it, cyc.end());
        standard_cycles.push_back(cyc);
    }

    sort(standard_cycles.begin(), standard_cycles.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[0] < b[0];
    });

    vector<int> reconstructed;
    for (const auto& cyc : standard_cycles) {
        for (int x : cyc) {
            reconstructed.push_back(x);
        }
    }

    vector<int> original_perm(n + 1);
    for (int i = 1; i <= n; ++i) {
        original_perm[i] = perm[i];
    }

    vector<int> test_perm(n + 1);
    for (int i = 0; i < reconstructed.size(); ++i) {
        test_perm[reconstructed[i]] = reconstructed[(i + 1) % reconstructed.size()];
    }

    for (int i = 1; i <= n; ++i) {
        if (test_perm[i] != original_perm[i]) {
            return false;
        }
    }

    return true;
}

int main() {
    ll n, k;
    cin >> n >> k;

    vector<vector<int>> valid_perms;
    vector<int> perm(n + 1);
    vector<int> used(n + 1, 0);

    function<void(int)> backtrack = [&](int pos) {
        if (pos > n) {
            if (is_valid_permutation(perm, n)) {
                valid_perms.push_back(perm);
            }
            return;
        }
        for (int i = 1; i <= n; ++i) {
            if (!used[i]) {
                used[i] = 1;
                perm[pos] = i;
                backtrack(pos + 1);
                used[i] = 0;
            }
        }
    };

    backtrack(1);

    sort(valid_perms.begin(), valid_perms.end());

    for (int i = 1; i <= n; ++i) {
        cout << valid_perms[k - 1][i] << " ";
    }
    cout << endl;

    return 0;
}
