#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;

struct Cycle {
    vector<int> elements;
    Cycle() {}
    Cycle(vector<int> e) : elements(e) {}
    bool operator < (const Cycle& other) const {
        return elements[0] < other.elements[0];
    }
};

vector<Cycle> get_cycles(const vector<int>& p) {
    int n = p.size();
    vector<bool> visited(n, false);
    vector<Cycle> cycles;
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            vector<int> cycle;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                cycle.push_back(j + 1);
                j = p[j] - 1;
            }
            cycles.push_back(Cycle(cycle));
        }
    }
    return cycles;
}

vector<int> to_permutation(const vector<Cycle>& cycles, int n) {
    vector<int> p(n, 0);
    for (const Cycle& cycle : cycles) {
        for (int i = 0; i < cycle.elements.size(); i++) {
            int from = cycle.elements[i];
            int to = cycle.elements[(i + 1) % cycle.elements.size()];
            p[from - 1] = to;
        }
    }
    return p;
}

vector<int> generate_kth_permutation(int n, ll k) {
    vector<int> p(n);
    for (int i = 0; i < n; i++) {
        p[i] = i + 1;
    }
    ll count = 0;
    do {
        if (count == k) {
            return p;
        }
        count++;
    } while (next_permutation(p.begin(), p.end()));
    return p;
}

vector<int> generate_kth_fixed_permutation(int n, ll k) {
    vector<int> p(n);
    for (int i = 0; i < n; i++) {
        p[i] = i + 1;
    }
    ll count = 0;
    do {
        vector<Cycle> cycles = get_cycles(p);
        for (Cycle& cycle : cycles) {
            sort(cycle.elements.rbegin(), cycle.elements.rend());
        }
        sort(cycles.begin(), cycles.end());
        vector<int> reconstructed = to_permutation(cycles, n);
        if (reconstructed == p) {
            if (count == k) {
                return p;
            }
            count++;
        }
    } while (next_permutation(p.begin(), p.end()));
    return p;
}

int main() {
    ll n, k;
    cin >> n >> k;
    k--; // convert to 0-based index
    vector<int> result = generate_kth_fixed_permutation(n, k);
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << result[i];
    }
    cout << endl;
    return 0;
}
