    vector<int> res(n);
    for (int i = 0; i < n; ++i) {
        res[i] = i + 1;
    }
    for (int i = 0; i < n; ++i) {
        long long f = 1;
        for (int j = 2; j <= n - i; ++j) {
            f *= j;
        }
        long long idx = (k - 1) / f;
        k -= idx * f;
        swap(res[i], res[i + idx]);
