using namespace std;

typedef long long ll;

ll n, k;

struct Perm {
    vector<int> p;
};

vector<Perm> valid;

void gen(int pos, vector<int>& p, vector<bool>& used) {
    if (pos == n) {
        valid.push_back({p});
        return;
    }
    for (int i = 0; i < n; ++i) {
        if (!used[i]) {
            p[pos] = i + 1;
            used[i] = true;
            gen(pos + 1, p, used);
            used[i] = false;
        }
    }
}

bool is_valid(const vector<int>& p) {
    vector<int> np(n);
    vector<bool> visited(n, false);
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            vector<int> cycle;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                cycle.push_back(j);
                j = p[j] - 1;
            }
            int max_val = *max_element(cycle.begin(), cycle.end());
            int max_idx = find(cycle.begin(), cycle.end(), max_val) - cycle.begin();
            rotate(cycle.begin(), cycle.begin() + max_idx, cycle.end());
            for (int k = 0; k < cycle.size(); ++k) {
                np[cycle[k]] = cycle[(k + 1) % cycle.size()] + 1;
            }
        }
    }
    return np == p;
}

int main() {
    cin >> n >> k;
    vector<int> p(n);
    vector<bool> used(n, false);
    gen(0, p, used);
    vector<Perm> filtered;
    for (auto& perm : valid) {
        if (is_valid(perm.p)) {
            filtered.push_back(perm);
        }
    }
    sort(filtered.begin(), filtered.end(), [](const Perm& a, const Perm& b) {
        return a.p < b.p;
    });
