    vector<vector<int>> cycles;
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            vector<int> cycle;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                cycle.push_back(j + 1); // 1-based
                j = p[j] - 1; // p[j] is 1-based
            }
            cycles.push_back(cycle);
        }
    }
    return cycles;
}

vector<int> standard_representation(const vector<int>& p) {
    vector<vector<int>> cycles = get_cycles(p);
    for (auto& cycle : cycles) {
        // Rotate to have max first
        int max_val = *max_element(cycle.begin(), cycle.end());
        auto it = find(cycle.begin(), cycle.end(), max_val);
        rotate(cycle.begin(), it, cycle.end());
    }
    // Sort cycles by first element
    sort(cycles.begin(), cycles.end(), [](const vector<int>& a, const vector<int>& b) {
        return a[0] < b[0];
    });
    // Flatten
    vector<int> result;
    for (const auto& cycle : cycles) {
        for (int num : cycle) {
            result.push_back(num);
        }
    }
    return result;
}

vector<int> generate_permutation(const vector<int>& standard) {
    int n = standard.size();
    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        p[i] = standard[i];
    }
    return p;
}

bool is_fixed(const vector<int>& p) {
    vector<int> standard = standard_representation(p);
    return p == standard;
}

