#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;

ll n, k;
vector<ll> ans;

void solve(ll pos) {
    if (pos > n) {
        k--;
        if (k == 0) {
            for (ll i = 0; i < n; i++) {
                cout << ans[i] << " ";
            }
            cout << endl;
            exit(0);
        }
        return;
    }
    for (ll i = pos; i <= n; i++) {
        if (i == pos) {
            ans[pos - 1] = pos;
            solve(pos + 1);
        } else {
            swap(ans[pos - 1], ans[i - 1]);
            ans[pos - 1] = i;
            ans[i - 1] = pos;
            solve(pos + 1);
            swap(ans[pos - 1], ans[i - 1]);
        }
    }
}

int main() {
    cin >> n >> k;
    ans.resize(n);
    for (ll i = 0; i < n; i++) {
        ans[i] = i + 1;
    }
    solve(1);
    return 0;
}
