#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct Cycle {
    vector<int> elements;
    Cycle() {}
    Cycle(vector<int> e) : elements(e) {}
    bool operator < (const Cycle& other) const {
        return elements[0] < other.elements[0];
    }
};

vector<Cycle> getStandardCycles(const vector<int>& p) {
    int n = p.size();
    vector<bool> visited(n, false);
    vector<Cycle> cycles;
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            vector<int> cycle;
            int current = i;
            while (!visited[current]) {
                visited[current] = true;
                cycle.push_back(current + 1);
                current = p[current] - 1;
            }
            sort(cycle.rbegin(), cycle.rend());
            cycles.emplace_back(cycle);
        }
    }
    sort(cycles.begin(), cycles.end());
    return cycles;
}

vector<int> cyclesToPermutation(const vector<Cycle>& cycles, int n) {
    vector<int> p(n);
    for (const auto& cycle : cycles) {
        int len = cycle.elements.size();
        for (int i = 0; i < len; ++i) {
            int from = cycle.elements[i];
            int to = cycle.elements[(i + 1) % len];
            p[from - 1] = to;
        }
    }
    return p;
}

bool isFixed(const vector<int>& p) {
    auto cycles = getStandardCycles(p);
    auto reconstructed = cyclesToPermutation(cycles, p.size());
    return p == reconstructed;
}

